n44822.content:
\begin{definition}\label{SpherePacking.scale}\lean{SpherePacking.scale}\uses{SpherePacking}\leanok
  Given a sphere packing $\mathcal{P}(X)$ with separation radius $r$, we defined the \emph{scaled packing} with respect to a real number $c > 0$ to be the packing $\mathcal{P}(cX)$, where $cX = \left\{ cx \in V \; \middle| \; x \in X \right\}$ has separation radius $cr$.
\end{definition}

n44824.content:
\begin{proof}\leanok
  The proof follows by direct computation:
  \[
    \Delta_{\mathcal{P}(cX)}(cR) = \frac{\operatorname{Vol}\!\left(\mathcal{P}(cX) \cap B_d(0, cR)\right)}{\operatorname{Vol}\!\left(B_d(0, cR)\right)} = \frac{c^d \cdot \operatorname{Vol}\!\left(\mathcal{P}(X) \cap B_d(0, R)\right)}{c^d \cdot \operatorname{Vol}\!\left(B_d(0, R)\right)}
    % = \frac{\Vol{\Pa(X) \cap B_d(0, R)}}{\Vol{B_d(0, R)}}
    = \Delta_{\mathcal{P}(X)}(R)
  \]
  where the second equality follows from applying the fact that scaling a (measurable) set by a factor of $c$ scales its volume by a factor of $c^d$ to the fact that $\mathcal{P}(cX) \cap B_d(0, cR) = c \cdot (\mathcal{P}(X) \cap B_d(0, cR))$.
\end{proof}

n44825.content:
\begin{lemma}\label{SpherePacking.scale_density}\lean{SpherePacking.scale_density}\uses{SpherePacking.scale}\leanok
  Let $\mathcal{P}(X)$ be a sphere packing and $c$ a positive real number. Then, the density of the scaled packing $\mathcal{P}(cX)$ is equal to the density of the original packing $\mathcal{P}(X)$.
\end{lemma}

n44829.content:
\begin{definition}\label{IsZLattice}\lean{IsZLattice}\leanok
  We say that an additive subgroup $\Lambda \leq \mathbb{R}^d$ is a \emph{lattice} if it is discrete and its $\mathbb{R}$-span contains all the elements of $\mathbb{R}^d$.
\end{definition}

n44831.content:
\begin{definition}\label{PeriodicSpherePacking}\lean{PeriodicSpherePacking}\uses{SpherePacking, IsZLattice}\leanok
  We say that a sphere packing $\mathcal{P}(X)$ is ($\Lambda$-)\emph{periodic} if there exists a lattice $\Lambda \subset \mathbb{R}^d$ such that for all $x \in X$ and $y \in \Lambda$, $x + y \in X$ (ie, $X$ is $\Lambda$-periodic).
\end{definition}

n44833.content:
\begin{theorem}\label{thm:periodic-packing-optimal}\uses{SpherePacking.density, def:Periodic-sphere-packing-constant}\lean{periodic_constant_eq_constant}\leanok
    For all $d$, the periodic sphere packing constant in $\mathbb{R}^d$ is equal to the sphere packing constant in $\mathbb{R}^d$.
\end{theorem}

n44835.content:
\begin{theorem}\label{theorem:CE_Main}\uses{E8-Lattice, SpherePackingConstant, SpherePacking.density, E8Packing-density, thm:g, thm:Cohn-Elkies-general}
  All \emph{periodic} packing $\mathcal{P} \subseteq \mathbb{R}^8$ has density satisfying $\Delta_{\mathcal{P}} \leq \Delta_{E_8} = \frac{\pi^4}{384}$, the density of the $E_8$ sphere packing (see \cref{E8Packing}).
\end{theorem}

n44836.content:
\begin{proof}
  Directly follows from \Cref{thm:Cohn-Elkies-general} applied to the function $f(x)=g(x/\sqrt{2})$ of \Cref{thm:g}.
  % TODO: Add a \ref to the actual proof at the end of this blueprint, I guess.
\end{proof}

n44837.content:
\begin{corollary}\label{corollary:upper-bound-E8}\uses{thm:periodic-packing-optimal, theorem:CE_Main}
  All packing $\mathcal{P} \subseteq \mathbb{R}^8$ has density satisfying $\Delta_{\mathcal{P}} \leq \Delta_{E_8}$.
\end{corollary}

n44838.content:
\begin{proof}
  This is a direct consequence of Theorem \cref{thm:periodic-packing-optimal} and \cref{theorem:CE_Main}.
\end{proof}

n44840.content:
\begin{proof}
  By definition, $\Delta_{E_8} \leq \Delta_8$, while \cref{corollary:upper-bound-E8} shows $\Delta_8 = \sup_{\mathrm{packing} \, \mathcal{P}} \leq \Delta_{E_8}$, and the result follows.
\end{proof}

n44842.content:
\begin{proof}\uses{SpherePacking}\leanok
  The high level idea is to prove that $\mathcal{P} \cap \mathcal{B}_d(R) = \left(\bigcup_{x \in X} \mathcal{B}_d\left(x, \frac{r}{2}\right)\right) \subseteq \bigcup_{x \in X \cap \mathcal{B}_d\left(R + \frac{r}{2}\right)} \mathcal{B}_d\left(x, \frac{r}{2}\right)$, and a similar inequality for the upper bound. The rest follows by rearranging and using the fact that the balls are pairwise disjoint.
\end{proof}

n44843.content:
\begin{lemma}\label{lemma:lattice-points-bound}\lean{PeriodicSpherePacking.aux2_ge',PeriodicSpherePacking.aux2_le'}\leanok
  For all $R$, we have the following inequality relating the number of lattice points from $\Lambda$ in a ball with the volume of the ball and the fundamental region $\mathcal{D}$:

  \[
    \frac{\mathrm{Vol}(\mathcal{B}_d(R - L))}{\mathrm{Vol}(\mathcal{D})}
    \leq \left|\Lambda \cap \mathcal{B}_d(R)\right|
    \leq \frac{\mathrm{Vol}(\mathcal{B}_d(R + L))}{\mathrm{Vol}(\mathcal{D})}
  \]
\end{lemma}

n44848.content:
\begin{proof}\leanok
  Write out the formula for volume of a ball and simplify. More specifically, we have $\mathrm{Vol}(\mathcal{B}_d(R)) = R^d \pi^{d / 2} / \Gamma\left(\frac{d}{2} + 1\right)$, so $\mathrm{Vol}(\mathcal{B}_d(R)) / \mathrm{Vol}(\mathcal{B}_d(R + C)) = R^d / (R + C)^d = \left(1 - \frac{1}{R + C}\right)^d = 1$.
\end{proof}

n44849.content:
\begin{theorem}\label{theorem:psp-density}\uses{SpherePacking.density}\lean{PeriodicSpherePacking.density_eq}\leanok
  For a periodic sphere packing $\mathcal{P} = \mathcal{P}(X)$ with centers $X$ periodic to the lattice $\Lambda$ and separation $r$,

  \[
    \Delta_{\mathcal{P}} = |X / \Lambda| \cdot \frac{\operatorname{Vol}\!\left(\mathcal{B}_d(r / 2)\right)}{\operatorname{Vol}\!\left(\mathbb{R}^d / \Lambda\right)}
  \]
\end{theorem}

n44850.content:
\begin{proof}\uses{lemma:sp-finite-density-bound, lemma:lattice-points-bound, lemma:periodic-points-bounds, lemma:volume-ball-ratio-limit}\leanok
  Fix any fundamental domain $\mathcal{D}$ (induced by any basis) of the lattice $\Lambda$. Combining \cref{lemma:sp-finite-density-bound}, \cref{lemma:lattice-points-bound} and \cref{lemma:periodic-points-bounds}, we get the following inequality for the \textit{finite} density:

  \[
    |X / \Lambda| \cdot \frac{\operatorname{Vol}\!\left(\mathcal{B}_d(r / 2)\right)}{\operatorname{Vol}\!\left(\mathbb{R}^d / \Lambda\right)} \cdot \frac{\operatorname{Vol}\!\left(\mathcal{B}_d(R - r / 2 - 2L)\right)}{\operatorname{Vol}\!\left(\mathcal{B}_d(R)\right)}
    \leq \Delta_{\mathcal{P}}(R)
    \leq |X / \Lambda| \cdot \frac{\operatorname{Vol}\!\left(\mathcal{B}_d(r / 2)\right)}{\operatorname{Vol}\!\left(\mathbb{R}^d / \Lambda\right)} \cdot \frac{\operatorname{Vol}\!\left(\mathcal{B}_d(R + r / 2 + 2L)\right)}{\operatorname{Vol}\!\left(\mathcal{B}_d(R)\right)}
  \]

  Taking limit on both sides as $R \to \infty$ and apply the Sandwich theorem and \cref{lemma:volume-ball-ratio-limit}, we get

  \[
    \Delta_{\mathcal{P}} = \limsup_{R \to \infty} \Delta_{\mathcal{P}}(R) = \lim_{R \to \infty} \Delta_{\mathcal{P}}(R) = |X / \Lambda| \cdot \frac{\operatorname{Vol}\!\left(\mathcal{B}_d(r / 2)\right)}{\operatorname{Vol}\!\left(\mathbb{R}^d / \Lambda\right)}
  \]
\end{proof}

n44852.content:
\begin{definition}{($E_8$-lattice, Definition 2)}\label{E8-Matrix}\lean{E8Matrix}\leanok
  We define the \emph{$E_8$ basis vectors} to be the set of vectors
  \[ \mathcal{B}_8 =
  \left\{
    \begin{bmatrix}
      1 \\ -1 \\ 0 \\ 0 \\ 0 \\ 0 \\ 0 \\ 0
    \end{bmatrix},
    \begin{bmatrix}
      0 \\ 1 \\ -1 \\ 0 \\ 0 \\ 0 \\ 0 \\ 0
    \end{bmatrix},
    \begin{bmatrix}
      0 \\ 0 \\ 1 \\ -1 \\ 0 \\ 0 \\ 0 \\ 0
    \end{bmatrix},
    \begin{bmatrix}
      0 \\ 0 \\ 0 \\ 1 \\ -1 \\ 0 \\ 0 \\ 0
    \end{bmatrix},
    \begin{bmatrix}
      0 \\ 0 \\ 0 \\ 0 \\ 1 \\ -1 \\ 0 \\ 0
    \end{bmatrix},
    \begin{bmatrix}
      0 \\ 0 \\ 0 \\ 0 \\ 0 \\ 1 \\ 1 \\ 0
    \end{bmatrix},
    \begin{bmatrix}
      -1/2 \\ -1/2 \\ -1/2 \\ -1/2 \\ -1/2 \\ -1/2 \\ -1/2 \\ -1/2
    \end{bmatrix},
    \begin{bmatrix}
      0 \\ 0 \\ 0 \\ 0 \\ 0 \\ 1 \\ -1 \\ 0
    \end{bmatrix}
  \right\}
  \]
\end{definition}

n44853.content:
\begin{theorem}\label{E8-defs-equivalent}\lean{span_E8Matrix}\uses{E8-Set, E8-Matrix}\leanok
  The two definitions above coincide, i.e. $\Lambda_8 = \mathrm{span}_{\mathbb{Z}}(\mathcal{B}_8)$.
\end{theorem}

n44856.content:
\begin{proof}\leanok
  It suffices to prove that $\mathcal{B}_8 \in \mathrm{GL}_8(\mathbb{R})$. We prove this by explicitly defining the inverse matrix $\mathcal{B}_8^{-1}$ and proving $\mathcal{B}_8 \mathcal{B}_8^{-1} = I_8$, which implies that $\det(\mathcal{B}_8)$ is nonzero. See the Lean code for more details.,
\end{proof}

n44857.content:
\begin{lemma}\label{E8-Lattice}\lean{E8Lattice}\uses{E8-Set, E8-defs-equivalent}\leanok
  $\Lambda_8$ is an additive subgroup of $\mathbb{R}^8$.
\end{lemma}

n44858.content:
\begin{proof}\leanok
  Trivially follows from that $\Lambda_8 \subseteq \mathbb{R}^8$ is the $\mathbb{Z}$-span of $\mathcal{B}_8$ and hence an additive group.
\end{proof}

n44859.content:
\begin{lemma}\label{E8-vector-norms}\lean{E8_norm_eq_sqrt_even}\uses{E8-defs-equivalent}\leanok
  All vectors in $\Lambda_8$ have norm of the form $\sqrt{2n}$, where $n$ is a nonnegative integer.
\end{lemma}

n44860.content:
\begin{proof}\leanok
  Writing $\vec{v} = \sum_i c_i\mathcal{B}_8^i$, we have $\|v\|^2 = \sum_i \sum_j c_ic_j (\mathcal{B}_8^i \cdot \mathcal{B}_8^j)$. Computing all $64$ pairs of dot products and simplifying, we get a massive term that is a quadratic form in $c_i$ with even integer coefficients, concluding the proof.
\end{proof}

n44861.content:
\begin{lemma}\label{instDiscreteE8Lattice}\lean{instDiscreteE8Lattice}\uses{E8-vector-norms}\leanok
  $c\Lambda_8$ is discrete, i.e. that the subspace topology induced by its inclusion into $\mathbb{R}^8$ is the discrete topology.
\end{lemma}

n44862.content:
\begin{proof}\leanok
  Since $\Lambda_8$ is a topological group and $+$ is continuous, it suffices to prove that $\{0\}$ is open in $\Lambda_8$. This follows from the fact that there is an open ball $\mathcal{B}(\sqrt{2}) \subseteq \mathbb{R}^8$ around it containing no other lattice points, since the shortest nonzero vector has norm $\sqrt{2}$.
\end{proof}

n44863.content:
\begin{lemma}\label{instLatticeE8}\lean{instIsZLatticeE8Lattice}\uses{instDiscreteE8Lattice, E8-is-basis}\leanok
  $c\Lambda_8$ is a $\mathbb{Z}$-lattice, i.e. it is discrete and spans $\mathbb{R}^8$ over $\mathbb{R}$.
\end{lemma}

n44864.content:
\begin{proof}\leanok
  The first part is by \cref{instDiscreteE8Lattice}, and the second part follows from that $\mathcal{B}_8$ is a basis (\cref{E8-is-basis}) and hence linearly independent over $\mathbb{R}$.
\end{proof}

