\begin{theorem}\label{thm:g}\uses{thm:g1}
There exists a radial Schwartz function $g:\mathbb{R}^8\to\mathbb{R}$ which satisfies:
\begin{align}
g(x)&\leq 0\mbox{ for } \|x\|\geq \sqrt{2} \label{eqn:g1}\\
\widehat{g}(x)&\geq0\mbox{ for all } x\in\mathbb{R}^8\label{eqn:g2}\\
g(0)&=\widehat{g}(0)=1.\label{eqn:g3}
\end{align}
\end{theorem}

