n45011.content:
\begin{definition}\label{def:b-definition}\uses{def:psiI-psiT-psiS}
Define $b_\mathrm{rad}: \mathbb{R}\to \mathbb{C}$ by
\begin{equation}
    \label{eqn:b-definition}
    b_\mathrm{rad}(r) := J_1(r) + J_2(r) + J_3(r) + J_4(r) + J_5(r) + J_6(r)
\end{equation}
where for $r \in \mathbb{R}$,
\begin{align}
    J_1(r) &:= \int_{-1}^{-1 + i} \psi_T(z) e^{\pi i r z} \, \mathrm{d}z, \label{eqn:J1} \\
    J_2(r) &:= \int_{-1 + i}^{i} \psi_T(z) e^{\pi i r z} \, \mathrm{d}z, \label{eqn:J2} \\
    J_3(r) &:= \int_{1}^{1 + i} \psi_T(z) e^{\pi i r z} \, \mathrm{d}z, \label{eqn:J3} \\
    J_4(r) &:= \int_{1 + i}^{i} \psi_T(z) e^{\pi i r z} \, \mathrm{d}z, \label{eqn:J4} \\
    J_5(r) &:= -2 \int_{0}^{i} \psi_I(z) e^{\pi i r z} \, \mathrm{d}z, \label{eqn:J5} \\
    J_6(r) &:= -2 \int_{i}^{i \infty} \psi_S(z) e^{\pi i r z} \, \mathrm{d}z. \label{eqn:J6}
\end{align}
Here all the contours are straight line segments.
Then we define $b : \mathbb{R}^8 \to \mathbb{C}$ by $b(x) := b_\mathrm{rad}(\|x\|^2)$.
\end{definition}

