        |\psi_T(z)| &\le C_T e^{2\pi \Im z}, \label{eqn:psiT-bound} \\
        |\psi_S(z)| &\le C_S e^{- \pi \Im z} \label{eqn:psiS-bound}
    \end{align}
\end{lemma}

